class fifo_scoreboard extends uvm_scoreboard;
  `uvm_component_utils(fifo_scoreboard)

  uvm_analysis_imp #(fifo_transaction, fifo_scoreboard) analysis_export;

  logic [7:0] model_q[$];
  bit         pending_read;
  logic [7:0] pending_expected_data;
  int         errors;
  int         checks;

  function new(string name = "fifo_scoreboard", uvm_component parent = null);
    super.new(name, parent);
    analysis_export = new("analysis_export", this);
    pending_read = 0;
    errors = 0;
    checks = 0;
  endfunction

  virtual function void write(fifo_transaction tr);
    bit exp_full, exp_empty;
    bit do_read, do_write;

    if (!tr.rst_n) begin
      model_q.delete();
      pending_read = 0;
      return;
    end

    exp_empty = (model_q.size() == 0);
    exp_full  = (model_q.size() == 8);
    checks++;

    // Check rd_data ONLY on the cycle after a read fired
    if (pending_read) begin
      if (tr.rd_data !== pending_expected_data) begin
        errors++;
        `uvm_error("FIFO_SCB", $sformatf("RD_DATA mismatch: expected=0x%02h got=0x%02h",
          pending_expected_data, tr.rd_data))
      end
      pending_read = 0;
    end

    // Check flags BEFORE applying this cycle's transaction
    // (DUT flags reflect pre-edge count; ref model state is also pre-edge)
    if (tr.empty !== exp_empty) begin
      errors++;
      `uvm_error("FIFO_SCB", $sformatf("EMPTY mismatch: expected=%0b got=%0b qsize=%0d",
        exp_empty, tr.empty, model_q.size()))
    end
    if (tr.full !== exp_full) begin
      errors++;
      `uvm_error("FIFO_SCB", $sformatf("FULL mismatch: expected=%0b got=%0b qsize=%0d",
        exp_full, tr.full, model_q.size()))
    end

    // Apply transaction to ref model
    do_read  = tr.r_en && !exp_empty;
    do_write = tr.w_en && (!exp_full || do_read);

    if (do_read) begin
      pending_expected_data = model_q.pop_front();
      pending_read = 1;
    end
    if (do_write) begin
      model_q.push_back(tr.wr_data);
    end
  endfunction

  function void report_phase(uvm_phase phase);
    super.report_phase(phase);
    `uvm_info("FIFO_SCB", $sformatf("Scoreboard summary: checks=%0d errors=%0d remaining_items=%0d",
      checks, errors, model_q.size()), UVM_LOW)
    if (errors > 0)
      `uvm_error("FIFO_SCB", "TEST FAILED")
    else
      `uvm_info("FIFO_SCB", "TEST PASSED", UVM_LOW)
  endfunction
endclass

